import type jsPDF from "jspdf";

// ─────────────────────────────────────────────────────────────
// The house style every report PDF follows, so a report looks the
// same whichever module it comes from (GRC, CRM, Finance, ESG, HR and
// the GRC Health Score):
//   • a navy band at the top of every page with the TENANT's company
//     name, the report title, a subtitle and the date generated;
//   • a footer on every page: "Generated by Lexora" on the left and
//     "Page n of N" on the right.
// The same look is produced on the server for the reports the engine
// builds (common/utils/pdf/report-builder.util.ts).
// ─────────────────────────────────────────────────────────────

export const REPORT_COLORS = {
  band: [37, 43, 94] as [number, number, number],
  summaryHead: [99, 102, 241] as [number, number, number],
  sectionHead: [63, 63, 110] as [number, number, number],
  body: [30, 30, 30] as [number, number, number],
  muted: [140, 140, 140] as [number, number, number],
};

export const REPORT_MARGIN = 40;
export const REPORT_BAND_HEIGHT = 76;
/** Where content starts on every page, just under the band. */
export const REPORT_TOP = REPORT_BAND_HEIGHT + 24;

/** The signed-in tenant's company name (stored at login). */
export function tenantCompanyName(): string {
  try {
    const raw = localStorage.getItem("tenantUser");
    const name = raw ? JSON.parse(raw)?.businessName : "";
    return typeof name === "string" ? name.trim() : "";
  } catch {
    return "";
  }
}

export const reportStamp = () => new Date().toLocaleString();

export interface ReportHeaderInfo {
  company?: string;
  title: string;
  subtitle?: string;
  generatedAt?: string;
}

/** Paints the band on the current page. Safe to call more than once. */
export function drawReportHeader(doc: jsPDF, info: ReportHeaderInfo) {
  const w = doc.internal.pageSize.getWidth();
  const company = (info.company ?? tenantCompanyName()).trim();
  doc.setFillColor(...REPORT_COLORS.band);
  doc.rect(0, 0, w, REPORT_BAND_HEIGHT, "F");
  doc.setTextColor(255, 255, 255);
  if (company) {
    doc.setFont("helvetica", "bold").setFontSize(9);
    doc.text(company.toUpperCase(), REPORT_MARGIN, 22);
  }
  doc.setFont("helvetica", "bold").setFontSize(16);
  doc.text(info.title, REPORT_MARGIN, 42);
  doc.setFont("helvetica", "normal").setFontSize(9);
  if (info.subtitle) doc.text(info.subtitle, REPORT_MARGIN, 60);
  doc.text(
    `Generated ${info.generatedAt ?? reportStamp()}`,
    w - REPORT_MARGIN,
    60,
    {
      align: "right",
    },
  );
  // leave the document ready for body text
  doc.setTextColor(...REPORT_COLORS.body);
  doc.setFont("helvetica", "normal");
}

/** Stamps "Generated by Lexora" and page numbers on every page. */
export function drawReportFooters(doc: jsPDF) {
  const w = doc.internal.pageSize.getWidth();
  const h = doc.internal.pageSize.getHeight();
  const total = doc.getNumberOfPages();
  for (let i = 1; i <= total; i++) {
    doc.setPage(i);
    doc.setFont("helvetica", "normal").setFontSize(8);
    doc.setTextColor(...REPORT_COLORS.muted);
    doc.text("Generated by Lexora", REPORT_MARGIN, h - 20);
    doc.text(`Page ${i} of ${total}`, w - REPORT_MARGIN, h - 20, {
      align: "right",
    });
  }
}
